/** ADR-116: reproducible MIT core-js-pure URL bundle for isolated QuickJS. */

import { readFile, writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import { build } from "esbuild";

const root = fileURLToPath(new URL("../../../", import.meta.url));
const result = await build({
  stdin: {
    contents: `import URL from 'core-js-pure/actual/url/index.js';
import URLSearchParams from 'core-js-pure/actual/url-search-params/index.js';
Object.assign(globalThis, {URL, URLSearchParams});`,
    resolveDir: root + "tools",
  },
  bundle: true,
  write: false,
  format: "iife",
  platform: "neutral",
  target: "es2020",
  minify: true,
  legalComments: "inline",
});
const source = result.outputFiles[0].text;
if (source.includes("\x27\x27\x27")) throw Error("Dart raw delimiter");
const license = await readFile(root + "node_modules/core-js-pure/LICENSE", "utf8");
const output =
  "// Generated by tools/src/script/web-standards.mjs. Do not edit.\n" +
  "// core-js-pure 3.49.0, MIT. See third_party/core-js-pure.LICENSE.\n" +
  "const scriptUrlBootstrap = r\x27\x27\x27\n" +
  source +
  "\x27\x27\x27;\n";
const path = root + "client/lib/core/scripts/url_bootstrap.g.dart";
if (process.argv.includes("--check")) {
  if (
    (await readFile(path, "utf8")) !== output ||
    (await readFile(root + "client/third_party/core-js-pure.LICENSE", "utf8")) !== license
  )
    throw Error("Stale URL bundle");
} else {
  await writeFile(path, output);
  await writeFile(root + "client/third_party/core-js-pure.LICENSE", license);
}
